#include <bits/stdc++.h>using namespace std;using ll = long long; int main() {	// your code goes here    ll T;        cin >> T;        while(T --){        int n , k;        cin >> n >> k;                string s ;        cin >> s;                int cntW = 0;                for(int i = 0 ; i < k ; i ++){            if(s[i] == 'W'){                cntW ++;            }        }                int ans = cntW;                for(int i = k ; i < n ; i ++){            if(s[i - k] == 'W'){                cntW --;            }                        if(s[i] == 'W'){                cntW ++;            }                        ans = min(ans , cntW);        }                cout << ans << endl;    }}